10	const RESET_CLOCK_UPDATE_INTERVAL_MS = 30_000
11	
12	interface CodexRateLimitStatusProps {
13	    mobile?: boolean
14	}
15	
16	/** Account-wide Codex rate-limit status. Own subscription stays at this leaf boundary. */
17	export function CodexRateLimitStatus({ mobile = false }: CodexRateLimitStatusProps) {
18	    const rateLimitState = useCodexRateLimits()
19	    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
20	    const [currentTime, setCurrentTime] = useState(Date.now)
21	
22	    useEffect(() => {
23	        const interval = setInterval(() => setCurrentTime(Date.now()), RESET_CLOCK_UPDATE_INTERVAL_MS)
24	
25	        return () => clearInterval(interval)
26	    }, [])
27	
28	    const presentation = codexRateLimitPresentation(rateLimitState)
29	    if (!presentation) return null
30	    const { accessibleState, highestUsedPercent, nearLimit, reached, receivedAt, snapshot, visibleBuckets } = presentation
31	    const statusColor = reached ? 'error.main' : nearLimit ? 'warning.main' : 'text.secondary'
32	    const roundedHighestPercent = Math.round(highestUsedPercent)
33	    const openDetails = (event: MouseEvent<HTMLElement>) => {
34	        setAnchorElement(event.currentTarget)
35	    }
36	    const closeDetails = () => {
37	        setAnchorElement(null)
38	    }
39	    const accessibleName = `Codex usage ${roundedHighestPercent}% used${accessibleState}`
40	
41	    return (
42	        <>
43	            {mobile ? (
44	                <MobileStatusRow
45	                    accessibleName={accessibleName}
46	                    icon={<SpeedOutlined sx={{ fontSize: 18 }} />}
47	                    label="Codex usage"
48	                    onClick={openDetails}
49	                    tone={statusColor}
50	                    value={`${roundedHighestPercent}% used`}
51	                />
52	            ) : (
53	                <Button
54	                    aria-label={accessibleName}
55	                    onClick={openDetails}
56	                    size="small"
57	                    startIcon={<SpeedOutlined sx={{ fontSize: 14 }} />}
58	                    sx={{ color: statusColor, fontSize: 'inherit', minWidth: 0, p: 0.5, whiteSpace: 'nowrap' }}
59	                >
60	                    Codex {roundedHighestPercent}% used
61	                </Button>
62	            )}
63	            <StatusDetailsSurface anchorElement={anchorElement} labelId="codex-rate-limit-title" mobile={mobile} onClose={closeDetails}>
64	                <CodexRateLimitDetails
65	                    currentTime={currentTime}
66	                    reached={reached}
67	                    receivedAt={receivedAt}
68	                    snapshot={snapshot}
69	                    visibleBuckets={visibleBuckets}
70	                />
71	            </StatusDetailsSurface>
72	        </>
73	    )
74	}
