178	class CodexRuntimeService {
179	    constructor() {
180	        this.events = new EventTarget();
181	        this.publishedUpdateMismatches = new Set();
182	        this.snapshot = null;
183	        this.updateRequiredSnapshot = null;
184	    }
185	
186	    getSnapshot() {
187	        return this.snapshot ? structuredClone(this.snapshot) : null;
188	    }
189	
190	    subscribe(listener) {
191	        const handleRateLimits = (event) => listener(event.detail);
192	        this.events.addEventListener(RATE_LIMIT_EVENT, handleRateLimits);
193	        if (this.snapshot) listener(this.getSnapshot());
194	
195	        return () => this.events.removeEventListener(RATE_LIMIT_EVENT, handleRateLimits);
196	    }
197	
198	    subscribeUpdateRequired(listener) {
199	        const handleUpdateRequired = (event) => listener(event.detail);
200	        this.events.addEventListener(UPDATE_REQUIRED_EVENT, handleUpdateRequired);
201	        if (this.updateRequiredSnapshot) listener(structuredClone(this.updateRequiredSnapshot));
202	
203	        return () => this.events.removeEventListener(UPDATE_REQUIRED_EVENT, handleUpdateRequired);
204	    }
205	
206	    publishUpdateRequired(runningVersion, cacheVersion) {
207	        if (typeof runningVersion !== 'string' || runningVersion.length === 0) {
208	            throw new Error('Running Codex version is required');
209	        }
210	        if (typeof cacheVersion !== 'string' || cacheVersion.length === 0) {
211	            throw new Error('Codex cache client version is required');
212	        }
213	        const mismatchKey = `${runningVersion}\u0000${cacheVersion}`;
214	        if (this.publishedUpdateMismatches.has(mismatchKey)) return false;
215	
216	        this.publishedUpdateMismatches.add(mismatchKey);
217	        this.updateRequiredSnapshot = { cacheVersion, runningVersion };
218	        this.events.dispatchEvent(new CustomEvent(UPDATE_REQUIRED_EVENT, {detail: structuredClone(this.updateRequiredSnapshot)}));
219	
220	        return true;
221	    }
222	
223	    publishRateLimits(payload, observedAt, sparse = false) {
224	        if (!Number.isFinite(observedAt)) throw new Error('Invalid Codex rate-limit observation time');
225	        if (this.snapshot && observedAt < this.snapshot.observedAt) return false;
226	        if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return false;
227	        const buckets = normalizeBuckets(payload);
228	        const resetCredits = normalizeResetCredits(payload.rateLimitResetCredits);
229	        if (!buckets || resetCredits === undefined) return false;
230	        const currentBuckets = new Map((this.snapshot?.buckets ?? []).map((bucket) => [bucket.limitId, bucket]));
231	        if (sparse) {
232	            for (const bucket of buckets) currentBuckets.set(bucket.limitId, mergeBucket(currentBuckets.get(bucket.limitId), bucket));
233	        }
234	        const normalizedBuckets = (sparse ? [...currentBuckets.values()] : buckets).map(completeBucket);
235	        const rateLimitResetCredits = sparse && resetCredits === null
236	            ? this.snapshot?.rateLimitResetCredits ?? null
237	            : resetCredits;
238	        this.snapshot = {
239	            available: true,
240	            buckets: normalizedBuckets,
241	            observedAt,
242	            rateLimitResetCredits,
243	        };
244	        this.notify();
245	
246	        return true;
247	    }
248	
249	    publishUnavailable(observedAt) {
250	        if (!Number.isFinite(observedAt)) throw new Error('Invalid Codex rate-limit observation time');
251	        if (this.snapshot && observedAt < this.snapshot.observedAt) return false;
252	        this.snapshot = { available: false, buckets: [], observedAt, rateLimitResetCredits: null };
253	        this.notify();
254	
255	        return true;
256	    }
257	
258	    notify() {
259	        const snapshot = this.getSnapshot();
260	        this.events.dispatchEvent(new CustomEvent(RATE_LIMIT_EVENT, { detail: snapshot }));
261	    }
262	}
263	
264	module.exports = { CodexRuntimeService };
